// Normaliza la respuesta de Ollama y prepara los parametros de busqueda
let res = {};
try {
  const raw = $input.item.json.response;
  res = typeof raw === 'string' ? JSON.parse(raw) : (raw || {});
} catch (e) {
  res = {};
}
const keywords = String(res.keywords || res.tipo || 'PC').trim();
const presupuesto = Number(res.presupuesto) || 1000;
const tipo = String(res.tipo || 'Equipo').trim();
return { json: { q: keywords, pMax: presupuesto, tipo: tipo } };

// Normaliza respuesta de Rainforest API (Amazon)
const data = $input.item.json || {};
const products = [];
const parseAmazonPrice = (p) => {
  if (!p) return 0;
  if (typeof p.value === 'number') return p.value;
  if (p.raw) {
    const txt = String(p.raw).replace(/\u00a0/g,' ').trim();
    let n = txt.replace(/[^0-9.,]/g,'');
    if (n.includes('.') && n.includes(',')) n = n.replace(/\./g,'').replace(',', '.');
    else if (n.includes(',')) n = n.replace(',', '.');
    const v = parseFloat(n);
    return isFinite(v) ? v : 0;
  }
  return 0;
};
if (Array.isArray(data.search_results)) {
  data.search_results.forEach(r => {
    if (!r || !r.title || !r.link) return;
    const price = parseAmazonPrice(r.price) || parseAmazonPrice(r.price_upper);
    products.push({ source: 'Amazon', title: r.title, price: price || 0, link: r.link, image: r.image || '' });
  });
}
return [{ json: { source: 'Amazon', products } }];

// Normaliza respuesta de SerpApi (engine=google) para PcComponentes
const STORE = 'PcComponentes';
const DOMAIN = 'pccomponentes.com';
const data = $input.item.json || {};
const products = [];
const extractPrice = (text) => {
  if (!text) return 0;
  const m = String(text).match(/(\d{1,3}(?:[.,]\d{3})*(?:[.,]\d{1,2})?)\s*(?:\u20ac|EUR|euros?)/i);
  if (!m) return 0;
  let n = m[1];
  if (n.includes('.') && n.includes(',')) n = n.replace(/\./g,'').replace(',', '.');
  else if (n.includes(',') && !n.includes('.')) n = n.replace(',', '.');
  else if (n.includes('.')) {
    const parts = n.split('.');
    if (parts.length === 2 && parts[1].length === 3) n = parts.join('');
  }
  const v = parseFloat(n);
  return isFinite(v) ? v : 0;
};
const pushItem = (title, link, price) => {
  if (!title || !link) return;
  if (!String(link).toLowerCase().includes(DOMAIN)) return;
  products.push({ source: STORE, title: String(title).trim(), price: price || 0, link });
};
if (Array.isArray(data.organic_results)) {
  data.organic_results.forEach(r => {
    let price = 0;
    if (r.rich_snippet && r.rich_snippet.top && r.rich_snippet.top.detected_extensions) {
      price = Number(r.rich_snippet.top.detected_extensions.price) || 0;
    }
    if (!price && r.rich_snippet && r.rich_snippet.bottom && r.rich_snippet.bottom.detected_extensions) {
      price = Number(r.rich_snippet.bottom.detected_extensions.price) || 0;
    }
    if (!price) price = extractPrice(r.snippet);
    if (!price) price = extractPrice(r.title);
    pushItem(r.title, r.link, price);
  });
}
if (Array.isArray(data.shopping_results)) {
  data.shopping_results.forEach(r => {
    const price = Number(r.extracted_price) || extractPrice(r.price);
    pushItem(r.title, r.link, price);
  });
}
return [{ json: { source: STORE, products } }];

