// =====================================================
// PROCESAMIENTO Y GENERACION DE HTML CORPORATIVO
// =====================================================
const STORES = ['Amazon', 'PcComponentes', 'Coolmod', 'MediaMarkt'];

// 1) Recoger todos los productos normalizados de las 4 fuentes
const allProducts = [];
$input.all().forEach(item => {
  if (item && item.json && Array.isArray(item.json.products)) {
    allProducts.push(...item.json.products);
  }
});

// 2) Recuperar parametros de la peticion
const params = $('Preparar Busqueda').first().json || {};
const pMax = Number(params.pMax) || 9999;
const tipo = params.tipo || 'Equipo';
const query = params.q || '';

// 3) Filtrar (precio valido y dentro de presupuesto), deduplicar por link, ordenar por precio
const seen = new Set();
const valid = allProducts
  .filter(p => p && p.price > 0 && p.price <= pMax && p.title && p.link)
  .filter(p => { const k = String(p.link).split('?')[0]; if (seen.has(k)) return false; seen.add(k); return true; })
  .sort((a, b) => a.price - b.price);

// 4) Top 3 global y Top 5 por tienda
const top3 = valid.slice(0, 3);
const byStore = {};
STORES.forEach(s => byStore[s] = []);
valid.forEach(p => { if (byStore[p.source]) byStore[p.source].push(p); });
Object.keys(byStore).forEach(s => { byStore[s] = byStore[s].slice(0, 5); });

// 5) Helpers
const fmt = n => Number(n).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' \u20ac';
const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const trunc = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1).trim() + '\u2026' : s; };
const today = new Date().toLocaleDateString('es-ES', { day: '2-digit', month: 'long', year: 'numeric' });
const activeStores = STORES.filter(s => byStore[s].length > 0).length;
const bestPrice = valid.length ? valid[0].price : 0;
const saving = valid.length ? (pMax - valid[0].price) : 0;

// 6) Iconos SVG inline
const ico = {
  globe:  '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M2 12h20"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>',
