  '</div>' +
'</header>';

const summaryHtml = '<section class="summary">' +
  '<div class="card stat"><div class="stat-icon">' + ico.globe  + '</div><div class="stat-body"><span class="stat-label">Ofertas analizadas</span><span class="stat-value">' + valid.length + '</span></div></div>' +
