  '<div class="card stat"><div class="stat-icon">' + ico.tag    + '</div><div class="stat-body"><span class="stat-label">Mejor precio</span><span class="stat-value">' + (valid.length ? fmt(bestPrice) : '\u2014') + '</span></div></div>' +
