      '<td class="title-cell">' + esc(trunc(p.title, 90)) + '</td>' +
      '<td class="store-cell"><span class="chip">' + esc(p.source) + '</span></td>' +
      '<td class="price-cell">' + fmt(p.price) + '</td>' +
