    '</tr>').join('')
  : '<tr><td colspan="5" class="empty">Sin resultados dentro del presupuesto.</td></tr>';

const top3Html = '<section class="block hero">' +
  '<div class="block-hd">' +
    '<div class="block-icon block-icon-primary">' + ico.spark + '</div>' +
    '<div><h2>Top 3 - Recomendacion global</h2><p class="sub">Las tres mejores ofertas por precio entre todas las tiendas analizadas.</p></div>' +
  '</div>' +
  '<table class="table table-top3">' +
    '<thead><tr><th class="th-rank">#</th><th>Producto</th><th>Tienda</th><th class="th-price">Precio</th><th class="th-act">Enlace</th></tr></thead>' +
    '<tbody>' + top3Rows + '</tbody>' +
  '</table>' +
'</section>';

const storeBlocks = STORES.map(store => {
  const items = byStore[store];
  const rows = items.length
    ? items.map((p, i) => '<tr>' +
        '<td class="rank-cell"><span class="rank rank-store">' + (i + 1) + '</span></td>' +
        '<td class="title-cell">' + esc(trunc(p.title, 95)) + '</td>' +
        '<td class="price-cell">' + fmt(p.price) + '</td>' +
        '<td class="action-cell"><a class="btn-secondary" href="' + esc(p.link) + '">' + ico.link + '<span>Abrir</span></a></td>' +
      '</tr>').join('')
    : '<tr><td colspan="4" class="empty">Sin resultados dentro del presupuesto en esta tienda.</td></tr>';
  return '<section class="block store-block">' +
    '<div class="block-hd">' +
      '<div class="block-icon">' + ico.store + '</div>' +
      '<div><h3>' + esc(store) + ' <span class="muted">- Top 5</span></h3><p class="sub">' + items.length + ' oferta(s) validas dentro del presupuesto.</p></div>' +
    '</div>' +
    '<table class="table table-store">' +
      '<thead><tr><th class="th-rank">#</th><th>Producto</th><th class="th-price">Precio</th><th class="th-act">Enlace</th></tr></thead>' +
      '<tbody>' + rows + '</tbody>' +
    '</table>' +
  '</section>';
}).join('');

const footerHtml = '<footer class="ftr">' +
